
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_gapc_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_gapc", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.794964194139849e-02, -5.707100610216249e-02, -5.582443331857375e-02, -5.406662675757610e-02, -5.161015053659270e-02, -4.822377899534731e-02, -4.365521896347944e-02, -3.771372894828377e-02, -3.050206211925063e-02, -2.303802577376938e-02, -1.959852025324650e-02, -3.908564436371690e-02, -4.567899521908912e-02, -3.384417042567099e-02, -2.101199991910912e-02, -9.179637432046651e-03, -1.692789164111003e-03, -2.731341650212284e-05, -3.251813544265916e-08, -9.279673127325502e-12]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


